input.command:
probe() { out=$(/workspace/dataset/test4_executable --a "$1" --b 5 2>&1); ec=$?; printf '%-24s exit=%d | %s\n' "[$1]" "$ec" "$(printf '%s' "$out" | grep -oE "invalid int value: .*|ValueError: .*|field1 = [0-9]+|error: .*" | head -1)"; }
probeEq() { out=$(/workspace/dataset/test4_executable "--a=$1" --b 5 2>&1); ec=$?; printf '  =form %-18s exit=%d | %s\n' "[$1]" "$ec" "$(printf '%s' "$out" | grep -oE "invalid int value: .*|ValueError: .*|field1 = [0-9]+|error: .*" | head -1)"; }
for v in "-+5" "--5" "-5.5" "-.5" "-5." "-_1" "- 5" "-0009" "-١" "-x"; do probe "$v"; probeEq "$v"; done

toolUseResult:
InputValidationError: [
  {
    "code": "custom",
    "path": [
      "command"
    ],
    "message": "command contains control characters that would be hidden in the approval dialog"
  }
]

input.command:
cd /workspace/dataset
mk() { yes 9 | head -$1 | tr -d '\n'; }
for n in 10 50 100 1000 4299 4300 4301 5000 20000; do v=$(mk $n); out=$(./test4_executable "--a=$v" --b 5 2>&1); ec=$?; msg=$(printf '%s' "$out" | grep -aoE "ValueError: [^']*|Exceeds[^\"]*" | head -1); short=$(printf '%s' "$out" | grep -ao "invalid int value" | head -1); printf 'digits=%-6s exit=%d | %s %s\n' "$n" "$ec" "$short" "$msg"; done

cd /workspace/dataset
run(){ out=$(./test4_executable "--a=$1" --b 5 2>&1); ec=$?; printf '%-34s exit=%d | %s\n' "$2" "$ec" "$(printf '%s' "$out" | grep -aoE "ValueError: .*|invalid int value" | head -1)"; }
N(){ yes 9 | head -$1 | tr -d '\n'; }
U(){ yes 9 | head -$1 | tr -d '\n' | sed 's/\(.\)/\1_/g; s/_$//'; }
run "$(U 4300)" "4300 digits, underscore between each"
run "$(U 4301)" "4301 digits, underscore between each"
echo "--- unicode digits count?"
AD(){ for i in $(seq 1 $1); do printf '\xd9\xa9'; done; }
run "$(AD 4300)" "4300 Arabic-Indic digits"
run "$(AD 4301)" "4301 Arabic-Indic digits"
